import{_ as h,C as o,o as d,c as p,j as t,a,E as r,a8 as c}from"./chunks/framework.27XeWUA0.js";const s="/schedule-dashboard/thumbs/yt/xRJMiaUoD_8-640.webp",u="/schedule-dashboard/thumbs/yt/xRJMiaUoD_8-1280.webp",n="/schedule-dashboard/thumbs/yt/pZWPq_ZAmM4-640.webp",w="/schedule-dashboard/thumbs/yt/pZWPq_ZAmM4-1280.webp",Z=JSON.parse('{"title":"AI Digest · Fri 20 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-20","routine":"digest"},"relativePath":"digest/2026-11-20.md","filePath":"digest/[date].md"}'),m={name:"digest/2026-11-20.md"},g=s+" 640w, "+u+" 1280w",b=n+" 640w, "+w+" 1280w",v={id:"ai-digest-·-fri-20-nov-2026",tabindex:"-1"};function f(y,e,_,k,M,q){const i=o("Badge"),l=o("DayFilter");return d(),p("div",null,[t("h1",v,[e[0]||(e[0]=a("AI Digest · Fri 20 Nov 2026 ",-1)),r(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-fri-20-nov-2026","aria-label":'Permalink to "AI Digest · Fri 20 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 20 Nov 2026 · run date Fri 20 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` There are 2 new talks. The freshest is Thariq Shihipar's "The Sweet Side of the Bitter Lesson" (1:30 AM IST today), a reflective talk whose useful part is a demo of keeping a readable "spec" layer in a vibe-coded game. Lovable CTO Fabian Hedin's talk (yesterday, 7:30 PM IST) is in well-covered coding-agent and sandbox territory, but it's full of new architecture details and numbers and is the one to watch.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" No new uploads in the last 24 hours.")])],-1)),r(l),e[5]||(e[5]=c('<div class="grid cards2"><article class="it full" id="v-xRJMiaUoD_8" data-title="The Sweet Side of the Bitter Lesson — Thariq Shihipar, Independent" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=xRJMiaUoD_8" target="_blank" rel="noopener"><img src="'+s+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=xRJMiaUoD_8" target="_blank" rel="noopener">The Sweet Side of the Bitter Lesson — Thariq Shihipar, Independent</a></h3><div class="meta">AI Engineer · Thariq Shihipar, independent (formerly Anthropic) · uploaded 20 Nov, 1:30 AM IST · 19:08</div><div class="verdict v-skim"><b>Verdict:</b> skim from 10:41 — the opening is a light reflection, but the readable-spec-layer demo (10:41–16:35) is a practical idea you can copy.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 50 times before. New here: he argues the fix for losing track of vibe-coded work isn&#39;t more review. It&#39;s a human-readable &quot;spec&quot; layer of the codebase that you edit directly.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 25 times before. New here: he pairs the &quot;industrial revolution&quot; framing with a &quot;renaissance&quot; one, where craft and taste become what&#39;s economically valuable.</div><div class="sh">What he got wrong this year</div><ul><li><strong>Right calls:</strong> He says he called it early that models would edit and generate video, use HTML to check their own work, and help you plan and learn about your unknowns (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=41s" target="_blank" rel="noopener">0:41</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=72s" target="_blank" rel="noopener">1:12</a>)</li><li><strong>&quot;Bash is all you need&quot; was wrong:</strong> Agents leaned on Bash because of how they were trained early on. He now prefers MCP to CLIs, and code mode, skills and progressive disclosure are all options now (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=87s" target="_blank" rel="noopener">1:27</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=129s" target="_blank" rel="noopener">2:09</a>)</li><li><strong>&quot;React is all you need&quot; and &quot;diffusion will eat art&quot; were wrong too:</strong> Models now write HTML, React, Swift or Figma&#39;s own JSON with roughly the same quality. People are writing their own languages, and LLMs make art through code and by driving Blender, Photoshop or Figma. Models didn&#39;t force one &quot;alien&quot; way of working on us (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=131s" target="_blank" rel="noopener">2:11</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=238s" target="_blank" rel="noopener">3:58</a>)</li></ul><div class="sh">Jagged frontier vs smooth interior</div><ul><li><strong>Industrial revolution and renaissance at once:</strong> He says this year was about software factories that made shipping reliable. At the same time, every bit of creativity, utility and &quot;soul&quot; in software is becoming more valuable (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=282s" target="_blank" rel="noopener">4:42</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=353s" target="_blank" rel="noopener">5:53</a>)</li><li><strong>Smooth interior:</strong> Benchmarks track the jagged frontier (to-do app → Slack clone → &quot;build Mario Kart and port it to the Wii&quot;). He cares more about the broad area inside it where models do everything well. He expects the perfect model to need less QA and review from you (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=355s" target="_blank" rel="noopener">5:55</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=557s" target="_blank" rel="noopener">9:17</a>)</li><li><strong>Land-or-water map eval:</strong> In an eval he credits to a post online (the captions garble the name, likely Karpathy), you give a model a latitude/longitude and ask &quot;land or water?&quot;, then plot the answers as a map. Opus 4.6 gives a blurry Earth and Opus 5.5 an almost perfect one, a way to see general knowledge rather than benchmark scores (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=558s" target="_blank" rel="noopener">9:18</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=618s" target="_blank" rel="noopener">10:18</a>)</li></ul><div class="sh">Taking back control: a demo</div><ul><li><strong>The vibe-coding problem:</strong> On his Avatar/Smash-style isometric fighting game, the model made design choices for him (does the rock pass through the summoned wall? what speed, size, charge?). He lost track of what his characters did, got distracted and made less progress (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=641s" target="_blank" rel="noopener">10:41</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=773s" target="_blank" rel="noopener">12:53</a>)</li><li><strong>Two-part codebase:</strong> An engine folder he doesn&#39;t read, plus a &quot;spec&quot;/human folder with linted, English-like, well-commented code in real units (meters, not 0.5). This works as a ground truth and a custom scripting language for his game, so he can tweak a move&#39;s rock size directly or tab-complete new actions in Cursor. He still asks Claude for new building blocks (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=781s" target="_blank" rel="noopener">13:01</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=995s" target="_blank" rel="noopener">16:35</a>)</li><li><strong>Renaissance to-do list:</strong> He calls for new languages (efficient like Rust but modular, hot-reloadable and readable), new databases, servers, OS interactions and interaction paradigms, and a second look at old HCI research. His point is that we should decide what the future of work looks like (<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=1002s" target="_blank" rel="noopener">16:42</a>–<a href="https://www.youtube.com/watch?v=xRJMiaUoD_8&amp;t=1128s" target="_blank" rel="noopener">18:48</a>)</li></ul></div></article><article class="it full" id="v-pZWPq_ZAmM4" data-title="What it takes to set intelligence free — Fabian Hedin, CTO, Lovable" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=pZWPq_ZAmM4" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+b+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4" target="_blank" rel="noopener">What it takes to set intelligence free — Fabian Hedin, CTO, Lovable</a></h3><div class="meta">AI Engineer · Fabian Hedin, co-founder &amp; CTO, Lovable · uploaded 19 Nov, 7:30 PM IST · 22:26</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a rare, detailed look at a production long-running-agent architecture, with real numbers (best part 7:48–19:12).</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 91 times before. New here: Lovable&#39;s own architecture and numbers (over a billion tokens per minute, 700 deploys a day, agents running 10+ hours).</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 32 times before. New here: full-machine checkpoints including memory and running processes, restored in about 230 ms, with copy-on-write RAM forks.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 30 times before. New here: an honest account of how their 2023 multi-agent framework failed, and per-agent inboxes as the design that works now.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 41 times before. New here: little. The inner/outer verification loops are familiar, apart from feeding A/B tests and payment conversions back to the agent.</div><div class="sh">Lovable&#39;s agent history</div><ul><li><strong>Nearly died building for agents too early:</strong> In 2023, &quot;GPT Engineer&quot; made one LLM call per message and could build one-page apps. They then built an elaborate multi-agent framework (main agent spawning front-end/back-end specialists that messaged each other), and it &quot;just made the product worse&quot; (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=103s" target="_blank" rel="noopener">1:43</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=185s" target="_blank" rel="noopener">3:05</a>)</li><li><strong>Back to simple, then agents again:</strong> In late 2024 they went back to one main LLM with small retrieval models, which was fast and reliable. Now agents work, and Lovable runs over a billion tokens per minute through them (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=187s" target="_blank" rel="noopener">3:07</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=233s" target="_blank" rel="noopener">3:53</a>)</li><li><strong>Outcomes, not code:</strong> The platform is a coding agent (browser for verification, GitHub sync), plus cloud basics (DB, auth, storage, security scans, backups, logs), plus business tools (payments, email, SEO, Google/Meta ads, analytics). The agent is in the loop for all of it (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=462s" target="_blank" rel="noopener">7:42</a>)</li></ul><div class="sh">Agent runtime for 10-hour runs</div><ul><li><strong>No time cap:</strong> Agents used to be capped at 30 minutes because they weren&#39;t reliable. Now there&#39;s no limit, and runs can go 10+ hours. Each agent has an inbox that humans, other agents or scheduled jobs drop messages into, and the agent copies them into its own history (its &quot;trajectory&quot;) (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=473s" target="_blank" rel="noopener">7:53</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=598s" target="_blank" rel="noopener">9:58</a>)</li><li><strong>Git-style history:</strong> The trajectory is an append-only log where each event points to its parent. That lets them fork parallel agents at any point without copying the shared history, though branches can&#39;t be merged. Prompts are built from this log, so compaction can be tuned for each model&#39;s context length (a debug slider replays 156 events) (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=622s" target="_blank" rel="noopener">10:22</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=781s" target="_blank" rel="noopener">13:01</a>) (repeat)</li><li><strong>Stateless workers:</strong> Processes save to the history after every tool call, so a 10-hour task survives Lovable&#39;s 700 deploys a day (about one every 2 minutes), including urgent Linux kernel security patches (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=784s" target="_blank" rel="noopener">13:04</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=873s" target="_blank" rel="noopener">14:33</a>)</li></ul><div class="sh">The computer underneath</div><ul><li><strong>Checkpointed VMs:</strong> A &quot;golden checkpoint&quot; (OS, tools, dev server ready to start, including disk, memory and running processes) is copied in about 230 ms. Each turn is checkpointed so idle machines can spin down after about 10 minutes and resume in under a second without dropping in-flight requests. Forks power the &quot;drafts&quot; feature (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=899s" target="_blank" rel="noopener">14:59</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1009s" target="_blank" rel="noopener">16:49</a>)</li><li><strong>Memory tricks:</strong> Copy-on-write RAM makes forks almost free until pages are written. Memory is streamed in so the VM boots before its few hundred MB have arrived (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1016s" target="_blank" rel="noopener">16:56</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1081s" target="_blank" rel="noopener">18:01</a>)</li><li><strong>Vite rewritten in Rust:</strong> By forking Vite and dropping Node.js, previews went from 40 s to 3 s with a 6.5x smaller memory footprint, which makes many parallel agents trying different fixes affordable (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1082s" target="_blank" rel="noopener">18:02</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1152s" target="_blank" rel="noopener">19:12</a>)</li><li><strong>Verification loops:</strong> Inside each turn, the agent checks builds, lint and type errors, runtime errors and a headless browser. Between turns, it uses visitor behaviour, user feedback, automatic A/B tests and payment conversions so it can help optimise the business, not just the code (<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1158s" target="_blank" rel="noopener">19:18</a>–<a href="https://www.youtube.com/watch?v=pZWPq_ZAmM4&amp;t=1265s" target="_blank" rel="noopener">21:05</a>) (repeat)</li></ul></div></article></div>',1))])}const x=h(m,[["render",f]]);export{Z as __pageData,x as default};
